// Command urltemplates generates internal/api/urltemplates_gen.go: the
// path templates in api/openapi.yaml, which name the CLI's HTTP client
// spans ("GET /monitors/{monitorId}"). Run it through `go generate
// ./internal/api` after re-vendoring the spec; TestURLTemplatesUpToDate
// fails until the generated file matches the spec.
package main

import (
	"bytes"
	"flag"
	"fmt"
	"go/format"
	"os"
	"sort"

	yaml "gopkg.in/yaml.v3"
)

func main() {
	spec := flag.String("spec", "api/openapi.yaml", "OpenAPI document to read")
	out := flag.String("out", "internal/api/urltemplates_gen.go", "Go file to write")
	flag.Parse()
	if err := run(*spec, *out); err != nil {
		fmt.Fprintln(os.Stderr, "urltemplates:", err)
		os.Exit(1)
	}
}

func run(specPath, outPath string) error {
	data, err := os.ReadFile(specPath) // #nosec G304 -- developer-supplied path to the vendored spec
	if err != nil {
		return err
	}
	src, err := Generate(data)
	if err != nil {
		return err
	}
	return os.WriteFile(outPath, src, 0o644) // #nosec G306 -- generated source file, same mode as hand-written ones
}

// Generate renders the generated Go file for the OpenAPI document spec.
func Generate(spec []byte) ([]byte, error) {
	var doc struct {
		Paths map[string]any `yaml:"paths"`
	}
	if err := yaml.Unmarshal(spec, &doc); err != nil {
		return nil, fmt.Errorf("parsing spec: %w", err)
	}
	if len(doc.Paths) == 0 {
		return nil, fmt.Errorf("spec has no paths")
	}
	paths := make([]string, 0, len(doc.Paths))
	for p := range doc.Paths {
		paths = append(paths, p)
	}
	sort.Strings(paths)

	var b bytes.Buffer
	b.WriteString("// Code generated by internal/tools/urltemplates from api/openapi.yaml. DO NOT EDIT.\n\n")
	b.WriteString("package api\n\n")
	b.WriteString("// specURLTemplates are the path templates in api/openapi.yaml.\n")
	b.WriteString("var specURLTemplates = []string{\n")
	for _, p := range paths {
		fmt.Fprintf(&b, "\t%q,\n", p)
	}
	b.WriteString("}\n")
	return format.Source(b.Bytes())
}
